    name: {
      de: "Kathedrale Unserer Lieben Frau der Weisheit",
      hu: "Bölcsesség Miasszonyunk Katedrális",
      ro: "Catedrala Maicii Domnului a În?elepciunii",
      en: "Cathedral of Our Lady of Wisdom Butare"},
